import java.util.Scanner;

public class ScientificCalculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        boolean running = true;

        System.out.println("=====================================");
        System.out.println("   CONSOLE SCIENTIFIC CALCULATOR     ");
        System.out.println("=====================================");

        while (running) {
            displayMenu();
            System.out.print("Choose operation (1-8): ");
            int choice = scanner.nextInt();

            if (choice == 8) {
                System.out.println("Thank you for using Scientific Calculator. Goodbye!");
                running = false;
                break;
            }

            // TODO: Prompt for inputs and call respective math methods
            // Hint: Notice choice 6 (Square Root) only needs ONE number!
        }

        scanner.close();
    }

    public static void displayMenu() {
        System.out.println("\n1. Addition (+)");
        System.out.println("2. Subtraction (-)");
        System.out.println("3. Multiplication (*)");
        System.out.println("4. Division (/)");
        System.out.println("5. Power (x^y)");
        System.out.println("6. Square Root (√x)");
        System.out.println("7. Modulo (x % y)");
        System.out.println("8. Exit");
    }

    // TODO: Implement static methods for add, subtract, multiply, divide, power, squareRoot, modulo
}

